transform:rotate(-16deg)}.hero-spark{position:absolute;right:32%;top:24px;color:#b9e77d;font-size:19px;opacity:.8}.fixture-card,.panel,.stat-card{background:#fff;border:1px solid #e9eeea;border-radius:12px;box-shadow:var(--shadow)}.fixture-card{padding:19px 20px;display:flex;flex-direction:column}.panel-top{display:flex;align-items:center;justify-content:space-between;color:#697970;font-size:9px;letter-spacing:.8px;font-weight:800}.status-pill,.form-badge{background:#f0f6e8;color:#5a7548;border-radius:20px;padding:5px 9px;font-size:8px;font-weight:800;letter-spacing:.3px}.fixture-date{margin-top:12px;color:#33453a;font-weight:700;font-size:11px}.fixture-date span{color:#929d96;font-weight:500}.fixture-teams{display:flex;justify-content:space-between;align-items:center;gap:7px;margin:15px 0 13px}.team{display:flex;align-items:center;gap:8px;max-width:40%;font-size:10px;line-height:1.35}.team b{font-size:10px}.team-crest{width:35px;height:35px;border-radius:10px}.opponent-crest{background:#f3eee6;color:#957650}.versus{font:700 11px 'Space Grotesk';color:#9eaaa2}.fixture-venue{color:#89958e;font-size:9px;border-top:1px solid #eff2ef;padding-top:10px}.fixture-link,.table-more{border:0;background:transparent;color:var(--green);font-size:10px;font-weight:800;padding:0;text-align:left;margin-top:11px}.fixture-link span,.table-more span{margin-left:5px;font-size:14px}.stats-strip{grid-column:1/-1;display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.stat-card{position:relative;padding:16px 17px;min-height:105px}.stat-label{display:block;color:#818e86;font-size:8px;font-weight:800;letter-spacing:.7px}.stat-symbol{position:absolute;right:14px;top:13px;width:29px;height:29px;border-radius:9px;background:#f1f6ec;color:#4a845d;display:grid;place-items:center;font-size:15px}.stat-value{display:block;margin-top:12px;font:700 24px 'Space Grotesk';letter-spacing:-.7px;color:#1d3024;white-space:nowrap}.stat-value small{font-size:13px}.stat-foot{display:block;margin-top